Item.method_code:
int savedSearchesCount = this.getItemCount();
for (int savedSearchIndex = 0; savedSearchIndex < savedSearchesCount; savedSearchIndex++)
{
	Item savedSearchItem = this.getItemByIndex(savedSearchIndex);
	string savedSearchCriteria = savedSearchItem.getProperty("criteria");
	string searchMode = savedSearchItem.getPropertyAttribute("search_mode", "keyed_name");
	bool isSimpleOrAdvancedSearch = searchMode == "Simple" || searchMode == "Advanced";
	if (string.IsNullOrEmpty(savedSearchCriteria) || !isSimpleOrAdvancedSearch)
	{
		continue;
	}

	#pragma warning disable IA1000 // Improper escaping in AML queries
	Item savedSearchCriteriaItem = this.newItem();
	savedSearchCriteriaItem.loadAML(savedSearchCriteria);
	#pragma warning restore IA1000 // Improper escaping in AML queries

	string propertyItemsWithActionGetXPath = "./*[not(self::Relationships)]/Item[@action='get']";
	Item propertyItemsWithActionGet = savedSearchCriteriaItem.getItemsByXPath(propertyItemsWithActionGetXPath);
	int propertyItemsCount = propertyItemsWithActionGet.getItemCount();
	for (int propertyIndex = 0; propertyIndex < propertyItemsCount; propertyIndex++)
	{
		Item propertyItem = propertyItemsWithActionGet.getItemByIndex(propertyIndex);

		propertyItem.removeAttribute("action");
	}

	savedSearchItem.setProperty("criteria", savedSearchCriteriaItem.ToString());
}

return this;
